import {
	AutoEnvAttributes,
	ReactNativeLDClient
} from '@launchdarkly/react-native-client-sdk'

if (!process.env.EXPO_PUBLIC_CREATE_LD_MOBILE_KEY) {
	throw new Error('EXPO_PUBLIC_CREATE_LD_MOBILE_KEY is not set')
}

export const launchDarklyClient = new ReactNativeLDClient(
	process.env.EXPO_PUBLIC_CREATE_LD_MOBILE_KEY,
	AutoEnvAttributes.Enabled
)
